        payload = JSON.parse(raw);
    } catch (e) {
        throw new Error('七猫详情接口未返回有效 JSON，请查看调试响应');
    }
    function isBook(value) {
        return value && typeof value === 'object' && !Array.isArray(value)
            && value.id != null && String(value.id) !== ''
            && typeof value.title === 'string' && value.title.replace(/\s/g, '') !== ''
            && !('books' in value) && !('filters' in value);
    }
    function isFlatBook(value) {
        return isBook(value) && ('author' in value || 'words_num' in value || 'image_link' in value);
    }
    if (payload && payload.data && isBook(payload.data.book)) {
        return JSON.stringify(payload.data.book);
    }
    if (payload && isFlatBook(payload.data)) {
        return JSON.stringify(payload.data);
    }
    if (isFlatBook(payload)) return JSON.stringify(payload);
    throw new Error('七猫响应中没有有效书籍详情；分类页或错误响应不能当作书籍解析');
})();
}).call(this);
}).call(this)

