function login() {}
function testQmLogin() {
  try {
    var token = qmLogin(true)
    java.longToast(token ? '七猫直连游客登录成功' : '七猫登录失败')
  } catch (e) { java.longToast('七猫直连失败：' + e.message) }
}
function resetQmLogin() {
  source.put('qm_token', '')
  source.put('qm_exp', '0')
  source.put('qm_uid', '')
  source.put('qm_device', '')
  java.longToast('七猫游客身份已重置，下次请求会自动注册')
}
function testQmEpubServer() {
  try {
    var base = qmEpubServiceBase.call(this)
    var token = String(result['◎ EPUB服务密钥'] || '').trim()
    if (!token) return java.longToast('请填写EPUB服务密钥')
    var saved = new Packages.java.util.HashMap()
    saved.put('◎ EPUB服务密钥', token)
    java.upLoginData(saved)
    var headers = {'accept':'text/plain'}
    if (token) headers['X-Qimao-Token'] = token
    var response = String(java.ajax(base + '/health,' + JSON.stringify({headers:headers})) || '').trim()
    java.longToast(response == 'ok' ? 'EPUB 解密服务连接成功，请刷新书籍目录和正文' : 'EPUB 服务响应异常：' + response)
  } catch (e) { java.longToast('EPUB 服务连接失败：' + e.message) }
}
function setQmExploreMode(mode) {
  mode = /^(novel|publish|audio|video)$/.test(String(mode)) ? String(mode) : 'novel'
  source.put('qm_explore_mode', mode)
  java.longToast('发现页已切换为：' + ({novel:'小说',publish:'图书',audio:'听书',video:'短剧/漫剧'}[mode]) + '，请返回发现页刷新')
}
function commentRefreshTip() {
  java.longToast('\n评论开关不会实时生效\n修改后请退出配置页，返回阅读页手动刷新正文')
}
function saveQmCommentSettings() {
  var color = String(result['◎ 段评颜色'] || '#000000').trim()
  if (!/^#[0-9a-fA-F]{6}$/.test(color)) return java.longToast('颜色格式应为 #000000')
  var splitColor = String(result['◎ 段评分色'] || '#E34B4B').trim()
  var hotColor = String(result['◎ 热评颜色'] || '#E23B3B').trim()
  if (!/^#[0-9a-fA-F]{6}$/.test(splitColor) || !/^#[0-9a-fA-F]{6}$/.test(hotColor)) return java.longToast('分色和热评颜色应为 #E34B4B 格式')
  var splitCount = Number(result['◎ 分色数值'] || 45)
  if (!isFinite(splitCount) || splitCount < 1) return java.longToast('分色数值请输入大于 0 的整数')
  var height = Number(result['◎ 半屏高度'] || 80)
  if (!isFinite(height) || height < 20 || height > 100) return java.longToast('半屏高度请输入 20 到 100')
  var map = new Packages.java.util.HashMap()
  map.put('◎ 段评颜色', color)
  map.put('◎ 段评分色', splitColor)
  map.put('◎ 热评颜色', hotColor)
  map.put('◎ 分色数值', String(Math.floor(splitCount)))
  map.put('◎ 半屏高度', String(height))
  map.put('◎ SVG大小', String(result['◎ SVG大小'] || 'text'))
  map.put('◎ 模板', String(result['◎ 模板'] || '起点'))
  map.put('◎ 评论主题', String(result['◎ 评论主题'] || '自动'))
  try { java.upLoginData(map) } catch (updateError) { return java.longToast('评论设置保存失败：' + updateError.message) }
  java.longToast('评论颜色、分色、主题和窗口高度已保存，刷新正文后生效')
}

