function jinghuafm() {
const {java, source} = this;	
function splitString(str) {
    const length = str.length;
    if (length < 15) {
        return length<9 ? [str] : [
            str.slice(0, 7),
            str.slice(7)
        ].filter(s => s);
    } else if (length < 20) {
        return [
            str.slice(0, 7),
            str.slice(7,13),
            str.slice(13)
        ].filter(s => s);
    }  else if (length < 24) {
        return [
            str.slice(0, 7),
            str.slice(7,13),
            str.slice(13,18),
            str.slice(18)
        ].filter(s => s);
    } else {
        return [
            str.slice(0, 7),
            str.slice(7, 13),
            str.slice(13, 18),
            str.slice(18, 22),
            str.slice(22)
        ].filter(s => s);
    }
}
function pingString(ss) {
let rr='';
let l1=ss.length;
for (let i1=0; i1<l1; i1++) {
	let c1=ss[i1], l2=c1.length;
	for (let i2=0; i2<l2; i2++) {
		let c2=c1.charAt(i2);
		rr += `<tspan x="${100+180*ii}" y="${180+170*(i2+i1)}">${c2}</tspan>`;
		}
		ii++;
	}
	return rr;
}

let [cb,cf] = colorz();

let bknm=String(this.book.name).replace(/\.{2,}/,'…');
bknm=bknm.match(/[a-z][a-z\+一-ꀀ\d…]+|[一-ꀀ\da-z]{2,}(?:\.\d+[一-ꀀ]*|[…？])?|[一-ꀀ]/gi);
let hz='';
let ii=0;

for (let char of bknm) {
	hz += pingString(splitString(char) );
	}

let svg = `<svg class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="5623" width="100%" height="100%">
<rect width="100%" height="150%" fill="#${cb}"/>
<g transform="scale(0.4) translate(1600,2500)">${Oranges}</g>
<text fill="#${cf}" stroke="#000000" stroke-width="2" font-weight="bold" font-size="150" text-anchor="middle" dominant-baseline="middle">
${hz}
</text>
</svg>`;
svg=java.base64Encode(svg);
return 'data:image/svg+xml;base64,'+svg;
}

